import cmath
import math


def rotate(points, degrees):
    turn = cmath.exp(1j * math.radians(degrees))
    out = []
    for x, y in points:
        w = complex(x, y) * turn
        out.append([w.real, w.imag])
    return out


def power_polar(z, n):
    r, theta = abs(z), cmath.phase(z)
    return r ** n * cmath.exp(1j * n * theta)
